import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'features/fitness/cubit/fitness_cubit.dart';import 'features/fitness/presentation/pages/fitness_page.dart';void main() {  WidgetsFlutterBinding.ensureInitialized();  runApp(    MultiBlocProvider(      providers: [        BlocProvider(create: (context) => FitnessCubit()),      ],      child: const MaterialApp(        debugShowCheckedModeBanner: false,        home: FitnessPage(),      ),    ),  );}